import{c as a,Q as n,j as e,m as t}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),d={name:"architecture.md"};function p(i,s,o,l,r,c){return n(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><h2 id="layer-responsibilities" tabindex="-1">Layer Responsibilities <a class="header-anchor" href="#layer-responsibilities" aria-label="Permalink to &quot;Layer Responsibilities&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP Request</span></span>
<span class="line"><span>     │</span></span>
<span class="line"><span>     ▼</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│  Middleware  │  JWT validation, CORS, logging</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│ Controller  │  Bind input → call service/util → return JSON</span></span>
<span class="line"><span>│             │  No raw SQL. No business logic.</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│   Service   │  Business logic, query building</span></span>
<span class="line"><span>│             │  May call initializers.DB directly</span></span>
<span class="line"><span>└──────┬──────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│    Utils    │  Stateless pure helpers</span></span>
<span class="line"><span>│             │  forms.go and model_mapper.go may read DB</span></span>
<span class="line"><span>└─────────────┘</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span>┌─────────────┐</span></span>
<span class="line"><span>│  GORM / DB  │  PostgreSQL via gorm.io/driver/postgres</span></span>
<span class="line"><span>└─────────────┘</span></span></code></pre></div><p><strong>Rule:</strong> never put DB queries directly in route handlers. Delegate to a service function.</p><hr><h2 id="directory-map" tabindex="-1">Directory Map <a class="header-anchor" href="#directory-map" aria-label="Permalink to &quot;Directory Map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmd/</span></span>
<span class="line"><span>  main.go                   Server entrypoint — hardcodes :8080</span></span>
<span class="line"><span>  migrations/main.go        GORM AutoMigrate runner</span></span>
<span class="line"><span>  seed/main.go              Seeder runner</span></span>
<span class="line"><span></span></span>
<span class="line"><span>internal/</span></span>
<span class="line"><span>  controllers/</span></span>
<span class="line"><span>    auth/                   Signup, Signin (public routes)</span></span>
<span class="line"><span>    base/                   BaseController — Index, Show, Update, Delete</span></span>
<span class="line"><span>    maid/                   Embeds BaseController, overrides Store</span></span>
<span class="line"><span>    user/                   Embeds BaseController, overrides Store</span></span>
<span class="line"><span>    tabs/                   GetTabs, AddNewTab, UpdateTab, DeleteTab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  middlewares/</span></span>
<span class="line"><span>    auth_middleware.go      JWT validation — sets &quot;user&quot; and &quot;userID&quot; in ctx</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  models/</span></span>
<span class="line"><span>    Users.go                User struct</span></span>
<span class="line"><span>    Maids.go                Maid struct (40+ fields)</span></span>
<span class="line"><span>    FormFields.go           Drives table columns, forms, search, filters</span></span>
<span class="line"><span>    UserTabs.go             Per-user tab config</span></span>
<span class="line"><span>    user_tab_column.go      Per-column visibility, order, width, locked state</span></span>
<span class="line"><span>    FilterGroup.go          Recursive filter tree (GROUP | FILTER nodes)</span></span>
<span class="line"><span>    Country.go / Skills.go / Language.go   Reference data</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  services/</span></span>
<span class="line"><span>    filter_service.go       ApplyFilters() — pure query builder, no DB exec</span></span>
<span class="line"><span>    query_service.go        QueryModelRecords() — executes on passed *gorm.DB</span></span>
<span class="line"><span>    tab_service.go          BindTabPayload, UpdateTabSettings, LoadFormFields,</span></span>
<span class="line"><span>                            UpsertTabColumns</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  utils/</span></span>
<span class="line"><span>    responses.go            ErrorResponse struct, ErrorJSON(), ErrorWithCodeJSON()</span></span>
<span class="line"><span>    search_builder.go       Multi-field ILIKE search with auto-JOIN</span></span>
<span class="line"><span>    reflection.go           DiscoverRelations() for auto-Preload</span></span>
<span class="line"><span>    forms.go                ResolveOptionsFromDataSource(), ResolveOptionsForField()</span></span>
<span class="line"><span>    model_mapper.go         GetModelForDataSource() — string name → model instance</span></span>
<span class="line"><span>    image_utils.go          ProcessImageUpload() — WebP conversion + BlurHash + upload</span></span>
<span class="line"><span>    tab_defaults.go         CreateDefaultTabsForUserModel()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  initializers/</span></span>
<span class="line"><span>    ConnectDataBase.go      initializers.DB (*gorm.DB global) with connection pool</span></span>
<span class="line"><span>    LoadEnvVars.go          Loads .env via godotenv</span></span>
<span class="line"><span>    storage.go              initializers.Storage (storage.Driver global)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  storage/</span></span>
<span class="line"><span>    driver.go               Driver interface</span></span>
<span class="line"><span>    local.go                Local disk implementation</span></span>
<span class="line"><span>    s3.go                   AWS S3 / Cloudflare R2 implementation</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  constants/</span></span>
<span class="line"><span>    contants.go             FormFieldType constants</span></span>
<span class="line"><span>    module.go               Model name constants (MAID, USER, etc.)</span></span>
<span class="line"><span>    options.go              Predefined select options (gender, visa, cities…)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  routes/routes.go          All route registrations</span></span>
<span class="line"><span></span></span>
<span class="line"><span>docs/</span></span>
<span class="line"><span>  swagger.json / swagger.yaml / docs.go    Auto-generated — DO NOT edit manually</span></span>
<span class="line"><span>  *.md                      This documentation</span></span></code></pre></div><hr><h2 id="route-map" tabindex="-1">Route Map <a class="header-anchor" href="#route-map" aria-label="Permalink to &quot;Route Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Controller</th><th>Auth</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/auth/signup</code></td><td>auth.Signup</td><td>Public</td></tr><tr><td>POST</td><td><code>/api/auth/signin</code></td><td>auth.Signin</td><td>Public</td></tr><tr><td>POST</td><td><code>/api/users/index</code></td><td>base.Index</td><td>JWT</td></tr><tr><td>POST</td><td><code>/api/users/</code></td><td>user.Store</td><td>JWT</td></tr><tr><td>GET</td><td><code>/api/users/:id</code></td><td>base.Show</td><td>JWT</td></tr><tr><td>PUT</td><td><code>/api/users/:id</code></td><td>base.Update</td><td>JWT</td></tr><tr><td>DELETE</td><td><code>/api/users/:id</code></td><td>base.Delete</td><td>JWT</td></tr><tr><td>POST</td><td><code>/api/maids/index</code></td><td>base.Index</td><td>JWT</td></tr><tr><td>POST</td><td><code>/api/maids/</code></td><td>maid.Store</td><td>JWT</td></tr><tr><td>GET</td><td><code>/api/maids/:id</code></td><td>maid.Show</td><td>JWT</td></tr><tr><td>PUT</td><td><code>/api/maids/:id</code></td><td>maid.Update</td><td>JWT</td></tr><tr><td>DELETE</td><td><code>/api/maids/:id</code></td><td>maid.Delete</td><td>JWT</td></tr><tr><td>GET</td><td><code>/api/tabs</code></td><td>tabs.GetTabs</td><td>JWT</td></tr><tr><td>POST</td><td><code>/api/tabs</code></td><td>tabs.AddNewTab</td><td>JWT</td></tr><tr><td>PUT</td><td><code>/api/tabs/:id</code></td><td>tabs.UpdateTab</td><td>JWT</td></tr><tr><td>DELETE</td><td><code>/api/tabs/:id</code></td><td>tabs.DeleteTab</td><td>JWT</td></tr><tr><td>GET</td><td><code>/ping</code></td><td>inline</td><td>Public</td></tr><tr><td>GET</td><td><code>/swagger/*any</code></td><td>SwaggerUI</td><td>Public</td></tr><tr><td>GET</td><td><code>/storage/*</code></td><td>static files</td><td>Public (local driver only)</td></tr></tbody></table><hr><h2 id="global-singletons" tabindex="-1">Global Singletons <a class="header-anchor" href="#global-singletons" aria-label="Permalink to &quot;Global Singletons&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Package</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>initializers.DB</code></td><td>initializers</td><td><code>*gorm.DB</code></td><td>PostgreSQL connection (pool configured)</td></tr><tr><td><code>initializers.Storage</code></td><td>initializers</td><td><code>storage.Driver</code></td><td>Active storage backend</td></tr></tbody></table><hr><h2 id="migration-approach" tabindex="-1">Migration Approach <a class="header-anchor" href="#migration-approach" aria-label="Permalink to &quot;Migration Approach&quot;">​</a></h2><p>This project uses <strong>GORM AutoMigrate</strong> — not SQL migration files.</p><p>To add a new table or column:</p><ol><li>Add or modify the struct in <code>internal/models/</code></li><li>Register the model in <code>cmd/migrations/main.go</code></li><li>Run: <code>go run ./cmd/migrations/main.go</code></li></ol><p>Never alter a model struct without running AutoMigrate. Never create raw SQL migration files.</p><hr><h2 id="known-issues" tabindex="-1">Known Issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known Issues&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Issue</th><th>Location</th></tr></thead><tbody><tr><td>1</td><td><code>UpdateTab</code> and <code>DeleteTab</code> are implemented but <strong>not registered</strong> in routes</td><td><code>routes/routes.go</code></td></tr><tr><td>2</td><td><code>BaseController.Store()</code> is empty — sub-controllers override it</td><td><code>base/base_controller.go</code></td></tr><tr><td>3</td><td><code>PORT</code> env var is declared but the server hardcodes <code>:8080</code></td><td><code>cmd/main.go</code></td></tr><tr><td>4</td><td>No test files (<code>*_test.go</code>) anywhere in the project</td><td>—</td></tr><tr><td>5</td><td><code>models.Patient</code> referenced in old Swagger docs — model does not exist</td><td><code>docs/</code></td></tr></tbody></table>`,22)])])}const h=a(d,[["render",p]]);export{g as __pageData,h as default};
